style.css:
@-moz-document domain("web.whatsapp.com") {
/* basis */
  :root{
    --bg:#fff7fb;        /* lichte achtergrond */
    --accent:#ffb6d5;    /* roze accent */
    --accent-2:#ffdfee;  /* zacht roze */
    --panel:#ffffffcc;   /* panel bg */
    --muted:#b08fa1;
    --bubble-me: linear-gradient(135deg, #ffecf6 0%, #ffeaf0 100%);
    --bubble-you: #fff;
    --text:#2b2430;
  }

  html, body, #app {
    background: var(--bg) !important;
    color: var(--text) !important;
    font-family: "Inter", "Segoe UI", system-ui, -apple-system, "Helvetica Neue", Arial !important;
  }

  /* sidebar (links) */
  [data-testid="chat-list"], ._3Kxus, ._2A8P4 {
    background: linear-gradient(180deg, #fffafc 0%, #fff3f8 100%) !important;
    backdrop-filter: blur(6px);
    border-right: 1px solid #ffe7f2 !important;
  }

  /* header bovenaan chat-list */
  header, [data-testid="chat-list-header"] {
    background: transparent !important;
    border-bottom: none !important;
    padding: 12px 16px !important;
  }

  /* zoekbalk */
  [data-testid="chat-list-search"], ._2S1VP {
    background: var(--panel) !important;
    border-radius: 12px !important;
    box-shadow: 0 4px 10px rgba(243, 214, 234, 0.6) !important;
  }

  /* chat-pane (midden) */
  [data-testid="conversation-panel"], ._1Flk2 {
    background: transparent !important;
    padding: 16px !important;
  }

  /* bericht bubbles */
  .message-in, .message-out, [data-testid="msg-container"] {
    border-radius: 16px !important;
    padding: 8px 12px !important;
    max-width: 78% !important;
  }

  /* jouw berichten (rechts) */
  .message-out, .copyable-area ._1wlJG ._1Gy50 {
    background: var(--bubble-me) !important;
    box-shadow: 0 6px 14px rgba(255, 182, 213, 0.18) !important;
    color: var(--text) !important;
    align-self: flex-end !important;
  }

  /* andermans berichten (links) */
  .message-in, .copyable-area ._1wlJG ._2f-RV {
    background: var(--bubble-you) !important;
    border: 1px solid #ffeef6 !important;
    color: var(--text) !important;
    align-self: flex-start !important;
  }

  /* tijdstempels en naam */
  .copyable-text ._3WHvu, ._2a1Yw {
    color: var(--muted) !important;
    font-size: 12px !important;
  }

  /* top header (rechts) */
  header._1QUKR {
    background: transparent !important;
    padding: 10px 16px !important;
  }

  /* input area onderaan */
  footer._2qX7L {
    background: transparent !important;
    border-top: none !important;
    padding: 10px 14px !important;
  }
  .pluggable-footer, ._13mgZ {
    background: var(--panel) !important;
    border-radius: 14px !important;
    padding: 8px !important;
    box-shadow: 0 6px 18px rgba(236, 206, 225, 0.45) !important;
  }

  /* knoppen accent */
  span[data-icon="clip"], span[data-icon="send"], button {
    filter: hue-rotate(300deg) saturate(1.1) !important;
    background: transparent !important;
  }

  /* avatars border */
  img[alt][src] {
    border-radius: 12px !important;
    box-shadow: 0 6px 14px rgba(255,182,213,0.25) !important;
  }

  /* scrollbar cozy */
  ::-webkit-scrollbar { width: 10px; height:10px; }
  ::-webkit-scrollbar-thumb { background: linear-gradient(180deg,#ffcce6,#ffb6d5); border-radius:10px; }
  ::-webkit-scrollbar-track { background: transparent; }

  /* kleine extra's */
  ._2a1Yw, ._3uMse {
    letter-spacing: 0.2px !important;
  }
}
